#include <iostream>
#include <sstream>
#include <iomanip>
#include <string>
#include <cstdlib>

struct PB {
  int progress; int total; int width; bool show_percentage; bool show_bar;
  std::string fill, lead, remainder, start, end;
  PB(): progress(0), total(100), width(50), show_percentage(true), show_bar(true),
        fill("="), lead(">"), remainder(" "), start("["), end("]") {}
  std::string str() const {
    std::ostringstream oss;
    if (show_bar) {
      oss << start;
      float ratio = (float)progress / (float)total;
      int pos = (int)(ratio * (float)width);
      for (int i = 0; i < width; ++i) {
        if (pos > i) oss << fill;
        else if (pos == i) oss << lead;
        else oss << remainder;
      }
      oss << end;
    }
    if (show_percentage) {
      if (show_bar) oss << " ";
      float ratio = (float)progress / (float)total;
      oss << std::fixed << std::setprecision(1) << (double)ratio * 100.0 << "%";
    }
    return oss.str();
  }
};

struct Pct {
  float value;
  Pct(float v): value(v) {}
  std::string str() const {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(1) << (double)value * 100.0 << "%";
    return oss.str();
  }
};

int main(int argc, char** argv) {
  // mode bar: ref bar p t w [showbar showpct]
  // mode pct: ref pct v
  std::string mode = argv[1];
  if (mode == "bar") {
    PB b; b.progress = atoi(argv[2]); b.total = atoi(argv[3]); b.width = atoi(argv[4]);
    if (argc > 6) { b.show_bar = atoi(argv[5]) != 0; b.show_percentage = atoi(argv[6]) != 0; }
    std::cout << b.str() << "\n";
  } else {
    Pct p(strtof(argv[2], 0));
    std::cout << p.str() << "\n";
  }
  return 0;
}

