#include <iostream>
#include <sstream>
#include <iomanip>
#include <string>
#include <cstdlib>
namespace indicators {
struct ProgressBar {
  int progress; int total; int width; bool show_percentage; bool show_bar;
  std::string fill, lead, remainder, start, end;
  ProgressBar(): progress(0), total(100), width(50), show_percentage(true), show_bar(true),
      fill("="), lead(">"), remainder(" "), start("["), end("]") {}
  void set_progress(int v){progress=v;} void set_total(int v){total=v;} void set_width(int v){width=v;}
  std::string str() const {
    std::ostringstream os;
    if (show_bar) {
      os << start;
      int completed = (int)((float)progress / (float)total * (float)width);
      for (int i = 0; i < width; ++i) {
        if (completed > i) os << fill; else if (completed == i) os << lead; else os << remainder;
      }
      os << end;
    }
    if (show_percentage) {
      if (show_bar) os << " ";
      os << std::fixed << std::setprecision(1) << ((double)((float)progress/(float)total) * 100.0) << "%";
    }
    return os.str();
  }
};
}
int main(int argc, char** argv) {
  indicators::ProgressBar b;
  if (argc > 3) { b.set_progress(atoi(argv[1])); b.set_total(atoi(argv[2])); b.set_width(atoi(argv[3])); }
  else { b.set_progress(0); b.set_total(0); b.set_width(10); }   // literal constants: inlinable+foldable
  std::cout << b.str() << "\n";
}
EOF
